"use client";

import { ArrowLeftIcon } from "lucide-react";
import Link from "next/link";
import { useState } from "react";
import { Button } from "@/registry/bases/base/ui/button";
import { CodeForm } from "@/registry/blocks/base/signup-03/components/code-form";
import {
  DetailsForm,
  type DetailsValues,
} from "@/registry/blocks/base/signup-03/components/details-form";
import { Logo } from "@/registry/blocks/base/signup-03/components/logo";

const SignUp = () => {
  const [details, setDetails] = useState<DetailsValues>({
    name: "",
    email: "",
  });
  const [codeSent, setCodeSent] = useState(false);

  const handleDetailsSubmit = (values: DetailsValues) => {
    setDetails(values);
    setCodeSent(true);
  };

  return (
    <div className="grid min-h-svh grid-rows-[1fr_auto_1fr] gap-8 bg-background p-4 sm:p-8">
      <div>
        {codeSent && (
          <Button onClick={() => setCodeSent(false)} variant="ghost">
            <ArrowLeftIcon data-icon="inline-start" />
            Use a different email
          </Button>
        )}
      </div>
      <div className="mx-auto flex w-full max-w-80 flex-col gap-8">
        <div className="flex flex-col items-center gap-2 text-center">
          <Logo className="mb-2 size-10" />
          <h1 className="font-medium text-2xl tracking-tight">
            {codeSent ? "Check your email" : "Create your account"}
          </h1>
          {codeSent ? (
            <p className="wrap-anywhere text-muted-foreground text-sm">
              We sent a 6-digit code to{" "}
              <span className="text-foreground">{details.email}</span>
            </p>
          ) : (
            <p className="text-muted-foreground text-sm">
              No password. We’ll email you a 6-digit code.
            </p>
          )}
        </div>
        {codeSent ? (
          <CodeForm />
        ) : (
          <>
            <DetailsForm
              defaultValues={details}
              onSubmit={handleDetailsSubmit}
            />
            <p className="text-center text-muted-foreground text-sm">
              Already have an account?{" "}
              <Link className="underline hover:text-foreground" href="#">
                Log in
              </Link>
            </p>
          </>
        )}
      </div>
      <p className="self-end text-balance text-center text-muted-foreground text-sm">
        By continuing you agree to the{" "}
        <Link className="underline hover:text-foreground" href="#">
          Terms
        </Link>{" "}
        and{" "}
        <Link className="underline hover:text-foreground" href="#">
          Privacy Policy
        </Link>
        .
      </p>
    </div>
  );
};

export default SignUp;

"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { useEffect } from "react";
import { Controller, useForm } from "react-hook-form";
import { z } from "zod";
import { Button } from "@/registry/bases/base/ui/button";
import {
  Field,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/registry/bases/base/ui/field";
import { Input } from "@/registry/bases/base/ui/input";

const formSchema = z.object({
  name: z.string().trim().min(1, "Enter your name."),
  email: z.string().email("Enter a valid email address."),
});

export type DetailsValues = z.infer<typeof formSchema>;

interface DetailsFormProps {
  defaultValues: DetailsValues;
  onSubmit: (values: DetailsValues) => void;
}

export const DetailsForm = ({ defaultValues, onSubmit }: DetailsFormProps) => {
  const form = useForm<DetailsValues>({
    defaultValues,
    resolver: zodResolver(formSchema),
  });

  // Coming back from the code step, put focus back on the email to edit.
  useEffect(() => {
    if (defaultValues.email) {
      form.setFocus("email");
    }
  }, [defaultValues.email, form]);

  return (
    <form noValidate onSubmit={form.handleSubmit(onSubmit)}>
      <FieldGroup>
        <Controller
          control={form.control}
          name="name"
          render={({ field, fieldState }) => (
            <Field data-invalid={fieldState.invalid}>
              <FieldLabel htmlFor="signup-name">Name</FieldLabel>
              <Input
                aria-invalid={fieldState.invalid}
                autoComplete="name"
                id="signup-name"
                placeholder="Alex Morgan"
                {...field}
              />
              <FieldError errors={[fieldState.error]} />
            </Field>
          )}
        />
        <Controller
          control={form.control}
          name="email"
          render={({ field, fieldState }) => (
            <Field data-invalid={fieldState.invalid}>
              <FieldLabel htmlFor="signup-email">Email</FieldLabel>
              <Input
                aria-invalid={fieldState.invalid}
                autoComplete="email"
                id="signup-email"
                placeholder="you@company.com"
                type="email"
                {...field}
              />
              <FieldError errors={[fieldState.error]} />
            </Field>
          )}
        />
        <Button className="w-full" type="submit">
          Send code
        </Button>
      </FieldGroup>
    </form>
  );
};

"use client";

import { REGEXP_ONLY_DIGITS } from "input-otp";
import { useEffect, useRef, useState } from "react";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/registry/bases/base/ui/input-otp";

const CODE_SLOTS = [0, 1, 2, 3, 4, 5];
const RESEND_DELAY_SECONDS = 30;

const formatSeconds = (seconds: number) =>
  `0:${seconds.toString().padStart(2, "0")}`;

export const CodeForm = () => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [code, setCode] = useState("");
  const [secondsLeft, setSecondsLeft] = useState(RESEND_DELAY_SECONDS);

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  useEffect(() => {
    if (secondsLeft === 0) {
      return;
    }
    const timer = setTimeout(() => setSecondsLeft(secondsLeft - 1), 1000);
    return () => clearTimeout(timer);
  }, [secondsLeft]);

  const handleComplete = (_code: string) => {
    // Verify the code with your auth provider.
  };

  const handleResend = () => {
    // Ask your auth provider to send a new code.
    setCode("");
    setSecondsLeft(RESEND_DELAY_SECONDS);
    inputRef.current?.focus();
  };

  return (
    <div className="flex min-h-63.5 flex-col items-center gap-5">
      <InputOTP
        aria-label="6-digit code"
        autoComplete="one-time-code"
        maxLength={CODE_SLOTS.length}
        onChange={setCode}
        onComplete={handleComplete}
        pattern={REGEXP_ONLY_DIGITS}
        ref={inputRef}
        value={code}
      >
        <InputOTPGroup>
          {CODE_SLOTS.map((slot) => (
            <InputOTPSlot index={slot} key={slot} />
          ))}
        </InputOTPGroup>
      </InputOTP>
      <p className="text-muted-foreground text-sm">
        Didn’t get it?{" "}
        {secondsLeft > 0 ? (
          `Resend in ${formatSeconds(secondsLeft)}`
        ) : (
          <button
            className="underline hover:text-foreground"
            onClick={handleResend}
            type="button"
          >
            Resend code
          </button>
        )}
      </p>
    </div>
  );
};
